OrderResult executeBuy(const std::string& orderId, const std::string& symbol, const std::string& orderType, int requestedQty, double limitPrice) {
    if (processedOrders.find(orderId) != processedOrders.end()) {
        return {"DUPLICATE", 0, 0, 0, 0};
    }

    int filledQty = 0;
    double totalCost = 0.0;
    auto originalAskBook = askBook;

    if (orderType == "MARKET") {
        for (auto it = askBook.begin(); it != askBook.end() && filledQty < requestedQty; ) {
            int qtyFilled = std::min(it->second, requestedQty - filledQty);
            totalCost += it->first * qtyFilled;
            filledQty += qtyFilled;
            it->second -= qtyFilled;
            if (it->second == 0) {
                it = askBook.erase(it);
            } else {
                ++it;
            }
        }
    } else if (orderType == "LIMIT") {
        for (auto it = askBook.begin(); it != askBook.end() && it->first <= limitPrice && filledQty < requestedQty; ) {
            int qtyFilled = std::min(it->second, requestedQty - filledQty);
            totalCost += it->first * qtyFilled;
            filledQty += qtyFilled;
            it->second -= qtyFilled;
            if (it->second == 0) {
                it = askBook.erase(it);
            } else {
                ++it;
            }
        }
