CheckoutResult checkout(int currentTime, const std::string& couponCode, bool paymentAuthorized) {
    CheckoutResult result;
    // 1. Check cart expiry
    if (currentTime - cartCreatedTime > cartExpiryMinutes * 60) {
        result.status = "EXPIRED";
        return result;
    }

    // 2. Check inventory
    for (const auto& item : items) {
        if (inventory[item.sku] < item.qty) {
            result.status = "INSUFFICIENT_INVENTORY";
            return result;
        }
    }

    // 3. Compute subtotal
    double subtotal = 0.0;
    for (const auto& item : items) {
        subtotal += item.price * item.qty;
    }
    result.subtotal = subtotal;

    // 4. Apply coupon
    if (!couponCode.empty()) {
        auto it = coupons.find(couponCode);
        if (it == coupons.end() || (it->second.singleUse && usedCoupons.find(couponCode) != usedCoupons.end())) {
            result.status = "COUPON_INVALID";
            return result;
        }
        const Coupon& coupon = it->second;
        if (subtotal < coupon.minPurchase) {
            result.status = "COUPON_INVALID";
            return result;
        }
        double eligibleSubtotal = 0.0;
        for (const auto& item : items) {
            if (coupon.excludedCategories.find(item.category) == coupon.excludedCategories.end()) {
                eligibleSubtotal += item.price * item.qty;
            }
        }
        result.discount = eligibleSubtotal * coupon.discountPct;
        if (coupon.singleUse) {
            usedCoupons.insert(couponCode);
        }
    } else {
        result.discount = 0.0;
    }

    // 5. Compute tax
    result.tax = 0.0;
    for (const auto& item : items) {
        auto taxRateIt = taxRates.find(item.category);
        double taxRate = (taxRateIt != taxRates.end()) ? taxRateIt->second : 0.0;
        result.tax += item.price * item.qty * taxRate;
    }

    // 6. Compute shipping
    double amountAfterDiscount = subtotal - result.discount;
    if (amountAfterDiscount >= 100) {
        result.shipping = 0.0;
    } else if (amountAfterDiscount >= 50) {
        result.shipping = 5.99;
    } else if (amountAfterDiscount >= 25) {
        result.shipping = 8.99;
    } else {
        result.shipping = 12.99;
    }

    // 7. Compute total
    result.total = subtotal - result.discount + result.tax + result.shipping;

    // 8. Check payment authorization
    if (!paymentAuthorized) {
        result.status = "AUTH_FAIL";
        return result;
    }

    // 9. Deduct inventory
    for (const auto& item : items) {
        inventory[item.sku] -= item.qty;
    }

    // 10. Log checkout
    auditLog.push_back("CHECKOUT:" + std::to_string(result.total) + ":" + "SUCCESS");

    // 11. Return SUCCESS
    result.status = "SUCCESS";
    return result;
}

